  "srRejection": "Abweisung (Angebot)",
  "srHowTitle": "So erkennst du sie",
  "srHowBody": "Die Unterstützung ist ein Niveau, an dem der Kurs aufhört zu fallen und abprallt: Die Nachfrage überwiegt das Angebot.\nDer Widerstand ist ein Niveau, an dem der Kurs aufhört zu steigen und dreht: Das Angebot überwiegt die Nachfrage.\nJe mehr Abpraller oder Abweisungen ein Niveau sammelt, desto zuverlässiger ist es.\nBricht der Kurs das Niveau mit Kraft und Volumen, tauschen Unterstützung und Widerstand ihre Rollen.",
  "srUseTitle": "Praktische Anwendung",
  "srUseBody": "Käufe nahe der Unterstützung suchen, mit dem Stop knapp darunter.\nGewinne mitnehmen oder nahe dem Widerstand verkaufen.\nDen Ausbruch erst handeln, wenn er bestätigt ist – idealerweise beim Retest des Niveaus.",
