  "tweezersBottomName": "Tweezer Bottom (Pinzette)",
  "tweezersBottomDesc": "Zwei aufeinanderfolgende Kerzen mit identischen Tiefs. Zeichen für starke Unterstützung und Kaufinteresse auf diesem Preisniveau.",
  "tweezersTopName": "Tweezer Top (Pinzette)",
  "tweezersTopDesc": "Zwei aufeinanderfolgende Kerzen mit identischen Hochs. Zeichen für starken Widerstand und Verkaufsinteresse auf diesem Preisniveau.",
  "evTitle": "Evidenzbasiertes Trading",
  "evIntro": "Was ist mit DATEN belegt — und nicht mit Versprechen? Hier bündeln wir, was akademische Studien, Regulierer und ein Jahrhundert an Daten von Fonds, Banken und Trading-Desks zeigen: wie viele wirklich verlieren, welche Strategien Jahrzehnte der Statistik überlebt haben und wie Profis Risiko steuern. Der rote Faden ist das Gesetz der großen Zahlen: ein Trade ist Glück; tausend Trades sind Statistik.",
  "hzTitle": "Handelszeiten & Saisonalität",
  "hzIntro": "Zu bestimmten Uhrzeiten und Terminen NEIGT der Markt zu ähnlichem Verhalten, getrieben von Geldflüssen (Eröffnungen, Daten, Schlusskurse, Verfall). Das sind keine festen Regeln oder Kaufsignale: es sind statistische Tendenzen, die dir helfen, WANN du handelst und wann du beiseite trittst. Alle Zeiten in Frankfurter Zeit (UTC+2) (±1 h je nach Sommerzeit).",
  "msTitle": "Marktstruktur",
  "msIntro": "Vor jeder Formation ist der Kurs eine Folge von Hochs und Tiefs. Die STRUKTUR zu lesen — ob diese Hochs und Tiefs steigen, fallen oder seitwärts laufen — verrät dir den Trend und wer das Sagen hat. Sie ist die Basis, auf der Chartmuster, SMC und fast alles andere ruhen. Hier lernst du, sie zu lesen und zu erkennen, wann sie kippt.",
  "mcTitle": "Makro: Zyklus, Zinsen & Rotation",
  "mcIntro": "Das makroökonomische Umfeld bewegt ganze Märkte — mehr als jeder einzelne Chart. Zinsen, Inflation und Wachstum bestimmen die Flut, die alle Boote hebt oder senkt. Es geht nicht ums Vorhersagen, sondern ums Positionieren: wissen, in welcher Zyklusphase wir sind und was dort meist funktioniert.",
  "cvTitle": "Ein Unternehmen fundiert bewerten",
  "cvIntro": "Die Fundamentalanalyse sucht, was ein Unternehmen wirklich wert ist, und vergleicht es mit dem Börsenkurs. Preis ≠ Wert: eine großartige Firma kann eine schlechte Anlage sein, wenn du zu viel zahlst, und eine mittelmäßige ein Schnäppchen. Hier lernst du, ihre Zahlen zu lesen und ihren Wert zu schätzen — über die 4 Basiskennzahlen hinaus.",
  "ofTitle": "Order Flow / Tape Reading",
  "ofIntro": "Der Kurs ist das Ergebnis; der Order Flow ist die Ursache. Hier lernst du, den echten Kauf- und Verkaufsdruck zu lesen — wer aggressiv ist, wo die Liquidität liegt, wo sie absorbiert wird — statt nur die fertige Kerze. Es braucht Level-2-Daten und Übung, aber es ist die Linse professioneller Daytrader.",
  "protoTitle": "Protokoll vor dem Handeln",
  "protoIntro": "Drei Werkzeuge, um Disziplin in konkrete Regeln zu verwandeln: deine Sicherungen, ein Einstiegsfilter und ein mentaler Check. Nutze sie in dieser Reihenfolge vor jeder Session und jedem Trade.",
  "brkTitle": "Stopp-Regeln (Sicherungen)",
  "brkIntro": "Lege vorab fest, wie viel du verlieren darfst, bevor du die Plattform schließt. Löst ein Limit aus, ist Schluss für heute: keine Ausnahmen, kein 'noch einer'.",
