  "pckTitle": "Checkliste vor dem Trade",
  "pckIntro": "Bevor du 'Kaufen' drückst, hake ab, was zutrifft. Je mehr Häkchen, desto besser der Trade; bleiben viele leer, überspring ihn — es kommt immer ein neuer.",
