  "structLogNote": "Der Scanner merkt sich, was er bei diesem Asset erkennt (Strukturbrüche und Kerzensignale), und behält es hier auch nach dem Neuladen. Blau hervorgehobene Einträge wurden in den letzten 24 Std. erstmals gesehen.",
