  "ideskTitle": "Der institutionelle Handelstisch",
  "ideskIntro": "Eine Bank oder ein Fonds «tradet» nicht wie Privatanleger: sie teilt die Arbeit auf Spezialisten auf, mit Prozessen, Limits und Technologie. Hier siehst du, wie ein professioneller Desk von innen funktioniert und was du dir aus jeder Rolle abschauen kannst, um wie ein Profi zu handeln, auch allein zu Hause.",
  "discTitle": "Professionelle Disziplin & Leistung",
  "discIntro": "Was den profitablen Profi vom Privatanleger unterscheidet, der seine Konto sprengt, ist nicht der Geheimindikator: es ist, wie sie Geist, Fehler und Stress unter Druck steuern. Das ist die «Software» des Elite-Traders, entliehen von institutionellen Desks, Piloten, Chirurgen und Hochleistungssportlern.",
  "mstTitle": "Margin-Stresstest",
  "mstIntro": "Bevor du eine gehebelte Position eröffnest, prüfe, ob du einen starken Einbruch überlebst. Gib Guthaben und Positionen ein und sieh Szenario für Szenario, wie viel du verlierst, wie viel Guthaben bleibt und ob ein Margin Call oder eine Liquidation eintritt. Die Kernfrage: „Überlebe ich −20 %?\".",
