  "ddrColDd": "Drawdown",
  "ddrColReq": "Nötige Erholung",
  "ddrNote": "Institutionelle Praxis: Fonds definieren einen maximal akzeptablen Drawdown (z. B. 15-20%) und automatische Regeln — bei -10% wird die Größe halbiert, bei -15% wird gestoppt und das System überprüft. Ein tägliches VaR (Value at Risk) begrenzt den Tagesverlust des Desks. Übernimm die Idee: Definiere DEIN Limit vor dem Trading, nicht während des Absturzes.",
  "heatCorrLabel": "Durchschnittliche Korrelation zwischen Positionen",
  "heatEffective": "Korrelationsbereinigtes effektives Risiko",
  "heatEffectiveSub": "zwischen voller Diversifikation (0%) und einem einzigen großen Trade (100%). Mehrere USD-Paare oder mehrere Tech-Aktien ≈ 60-90%.",
  "gkTitle": "Options-Griechen",
  "gkIntro": "Die Griechen messen, wie sich der Optionspreis ändert, wenn sich jede Variable bewegt: Basiswert, Zeit, Volatilität und Zinsen. Sie sind das Cockpit des Optionshändlers — ohne sie fliegst du blind. Jede Karte enthält ein Zahlenbeispiel; übe danach mit dem Black-Scholes-Rechner im Bereich Optionen.",
  "mlqTitle": "Margin & Liquidation bei Derivaten",
  "mlqIntro": "Wer gehebelte Futures oder Perpetuals handelt, lebt von seiner Margin. Die meisten Konten sterben nicht an schlechter Analyse, sondern daran, nicht zu verstehen, WIE und WANN die Börse liquidiert. Dieses Modul erklärt Margin-Modi, Positionsmodi, den Liquidationspreis und den Schutz vor Manipulations-Dochten.",
  "ntTitle": "News & Events handeln",
  "ntIntro": "High-Impact-Daten (NFP, CPI, Zinsen) bewegen Märkte in Sekunden. Zu wissen, was vorher, währenddessen und danach zu tun ist, trennt Chance von gesprengtem Konto. Nutze den Wirtschaftskalender im Dashboard.",
  "smTitle": "Marktsentiment",
  "smIntro": "Misst, was die Masse fühlt: Angst oder Gier. In Extremen ist Sentiment Contrarian-Treibstoff – wenn ALLE bullisch sind, fehlen Käufer. Ergänzt das COT in dieser Säule.",
  "imTitle": "Intermarket-Analyse",
  "imIntro": "Kein Markt bewegt sich allein (John Murphy). Dollar, Anleihen, Rohstoffe und Aktien sind verbunden: diese Beziehungen liefern den Makro-Kontext deiner Trades. Nicht umsonst 15 % der CMT-Prüfung.",
  "bcTitle": "Marktbreite, Zyklen & Saisonalität",
  "bcIntro": "Ein Index kann von 5 Mega-Caps getragen steigen, während der Rest sinkt: Marktbreite misst die INNERE Gesundheit. Zyklen und Saisonalität liefern das statistische 'Wann'. CMT-Stoff, den kaum ein Retail-Trader beachtet.",
  "bkrTitle": "Broker, Regulierung & Betrug",
  "bkrIntro": "Du kannst am Chart alles richtig machen und alles verlieren, wenn du falsch einzahlst. Dieses Modul zeigt, wie du einen Broker in 10 Minuten prüfst und Betrug erkennst.",
