  "aiCoachIntro_91e0e7": "Klicke auf {analyzeBold} und Claude Sonnet 4.5 prüft deine aktuelle Strategie: Stärken, Risiken, umsetzbare Verbesserungen und finales Urteil. Konzipiert als Senior-Coach für Volatility Trading.",
  "aiCoachAnalyze_91e0e8": "Analysieren",
