  "aiCoachReanalyze_91e0ea": "Neu analysieren",
  "aiCoachDisclaimer_91e0eb": "KI-generierte Analyse — stellt keine Finanzberatung dar. Immer mit eigenem Urteilsvermögen prüfen.",
  "bullishBias_91e0ec": "BULLISCHE Ausrichtung: Du gewinnst, wenn {symbol} steigt. Break-even bei Verfall ~${be}.",
  "bearishBias_91e0ed": "BÄRISCHE Ausrichtung: Du gewinnst, wenn {symbol} unter ${be} fällt.",
  "neutralBias_91e0ee": "NEUTRALE Ausrichtung: Du gewinnst, wenn {symbol} in einer Range bleibt. {berange}",
  "neutralBreakEvens_91e0ef": "Break-evens ${be1} und ${be2}.",
  "thetaNegative_91e0f0": "NEGATIVES Theta: Du zahlst Prämie, die täglich verfällt. Du brauchst eine Bewegung BALD, bevor der Zeitverfall den Wert erodiert.",
  "thetaPositive_91e0f1": "POSITIVES Theta: Du vereinnahmst Prämie. Die ZEIT SPIELT FÜR DICH — wenn der Kurs sich nicht bewegt, gewinnst du täglich durch Zeitverfall.",
  "thetaNeutral_91e0f2": "NEUTRALES Theta: Long- und Short-Positionen gleichen sich aus. Die Preisbewegung ist wichtiger als die Zeit.",
  "unlimitedRiskUp_91e0f3": "UNBEGRENZTES RISIKO nach oben. Erfordert hohe Margin und disziplinierten Stop-Loss.",
  "unlimitedRiskDown_91e0f4": "UNBEGRENZTES RISIKO nach unten. Erfordert hohe Margin und disziplinierten Stop-Loss.",
  "maxLossDefined_91e0f5": "MAXIMALER Verlust definiert: ${amount}. Du kannst nicht mehr als diesen Betrag verlieren, egal was passiert.",
  "assignPut_91e0f6": "Wenn {symbol} unter ${strike} fällt und du hältst, werden dir 100 Aktien/Kontrakt zum Strike-Preis zugeteilt.",
  "assignCall_91e0f7": "Wenn {symbol} über ${strike} steigt und du hältst, lieferst du 100 Aktien/Kontrakt (bei gedecktem Short Call) oder deckst mit Verlust (bei ungedecktem).",
  "ivHighLong_91e0f8": "HOHE IV ({iv}%): Du zahlst teure Prämien. Ein Volatilitätseinbruch nach Earnings kann Verluste verursachen, selbst wenn du die Richtung richtig hast.",
  "ivHighShort_91e0f9": "HOHE IV ({iv}%): Du vereinnahmst hohe Prämien. Günstiges Setup für Volatilitätsverkäufer.",
