  "trendRule4": "Avoid entering on the first touch — wait for the second or third bounce",
  "trendRule5": "A closed candle OUTSIDE the trend line is a break — don't fight it",
  "trendBreakTitle": "Trendlinien-Brüche",
  "trendBreakDesc": "When price decisively closes outside a trend line with strong momentum and volume, the trend may be reversing. Wait for a retest of the broken line before entering in the new direction.",
  "trendBullLine": "Bullish Trend Line",
  "trendBearLine": "Bearish Trend Line",
  "fundTab": "Grundlagen",
  "techTab": "Technisch",
  "ewTab": "Elliott-Wellen",
  "ichiTab": "Ichimoku",
  "ichiTitle": "Ichimoku Kinko Hyo",
  "smcTitle": "Smart Money / ICT",
  "optTitle": "Optionsstrategien",
  "optIntro": "Calls und Puts zu kombinieren erlaubt Positionen mit definiertem Risiko, die nicht nur von der Richtung, sondern auch von Volatilität und Zeitverfall profitieren. Nutze den Optionsrechner, um die Griechen und das Payoff-Diagramm jeder Strategie zu sehen.",
  "smcIntro": "Der 'Smart Money'-Ansatz (durch ICT populär geworden) versucht, den Spuren des institutionellen Geldes zu folgen: wo Orders aufgebaut werden, wie Retail-Liquidität gejagt wird und wohin der Kurs zurückkehrt. Er ist diskretionär – nutze ihn als Konfluenz, nicht als Zaubersystem.",
  "ichiIntro": "Ein japanisches 'Gleichgewichtsdiagramm auf einen Blick', entwickelt von Goichi Hosoda. Fünf Linien und eine projizierte 'Wolke' zeigen Trend, Unterstützung/Widerstand, Momentum und Einstiegssignale gleichzeitig – konzipiert, um den Markt auf einen Blick zu lesen. Sehr beliebt bei Forex und Krypto.",
  "ewTitle": "Elliott-Wellen-Theorie",
  "ewIntro": "Ralph Elliott beobachtete, dass die Massenpsychologie die Märkte in sich wiederholenden Wellenmustern bewegt. Der Kurs steigt in einer 5-welligen 'Antriebssequenz' in Trendrichtung und korrigiert dann in einer 3-welligen Sequenz dagegen. Dieselbe 5-3-Form wiederholt sich auf jeder Ebene, von Minuten bis zu Jahrzehnten.",
  "fundAnalTab": "Fundamental",
  "stylesTab": "Stile",
  "mechTab": "Mechanik",
  "volverAlDashboard": "Zurück zum Dashboard",
  "fundTitle": "Trading-Grundlagen",
  "fundIntro": "Die Kernkonzepte des Tradings auf verschiedenen Märkten verstehen",
