  "techIntro": "Preischarts und Indikatoren für zukünftige Marktbewegungen nutzen",
  "trendTitle": "Trendanalyse",
  "fundAnalTitle": "Fundamentalanalyse",
  "fundAnalIntro": "Wirtschaftliche Faktoren analysieren, die Märkte langfristig antreiben",
  "econCalTitle": "Wirtschaftskalender",
  "stylesTitle": "Trading-Stile",
