  "strat_when_ladder_long": "Sie erwarten entweder enge Range oder sehr große Bewegung, nichts dazwischen",
  "strat_csp_desc": "Put verkaufen und 100% des Strikes in bar hinterlegen. Gleiches Payoff wie ein Short Put, anderer Kapitaleinsatz.",
  "strat_protective_put_desc": "Aktie plus darunter gekaufter Put: eine Versicherung mit Selbstbehalt.",
  "strat_covered_put_desc": "Leerverkaufte Aktie plus verkaufter Put. Kassiert Prämie, solange der Kurs nicht steigt.",
  "strat_covered_strangle_desc": "Aktie plus je ein aus dem Geld verkaufter Call und Put. Doppelte Prämie, Verpflichtung auf beiden Seiten.",
  "strat_ratio_call_write_desc": "Aktie mit zwei verkauften Calls: einer gedeckt, einer nackt.",
  "strat_ratio_put_write_desc": "Leerverkaufte Aktie mit zwei verkauften Puts: einer gedeckt, einer nackt.",
  "strat_stock_repair_desc": "Auf eine Verlustposition: ein Call gekauft, zwei höher verkauft, um den Break-even ohne frisches Geld zu senken.",
  "strat_call_calendar_desc": "Nahen Call verkaufen, denselben Call später kaufen. Lebt davon, dass die Zeit im kurzen Bein schneller läuft.",
  "strat_put_calendar_desc": "Nahen Put verkaufen und denselben Put mit späterem Verfall kaufen.",
  "strat_call_diagonal_desc": "Calendar mit unterschiedlichen Strikes: das höhere Short-Bein gibt dem Zeitwert eine bullische Tendenz.",
  "strat_put_diagonal_desc": "Put-Calendar mit unterschiedlichen Strikes: das tiefere Short-Bein gibt eine bärische Tendenz.",
  "strat_double_calendar_desc": "Zwei Calendars, einer mit Puts darunter, einer mit Calls darüber. Zahlt, wenn der Kurs dazwischen endet.",
  "strat_double_diagonal_desc": "Doppel-Calendar mit weiter entfernten Long-Beinen: verbreitert die Gewinnzone gegen höheres Debit.",
  "strat_jelly_roll_desc": "Die Differenz zweier Synthetics auf denselben Strike in zwei Verfällen. Der Preis ist reiner Zins und Dividende.",
  "strat_pmcc_desc": "Ein tief im Geld liegender, langlaufender Call ersetzt die Aktie; dagegen wird ein naher Call verkauft. Covered Call ohne 100 Aktien.",
  "strat_zebra_desc": "Zwei im Geld gekaufte Calls gegen einen verkauften: Delta nahe 100 ohne Nettozeitwert.",
  "strat_risk_reversal_desc": "Finanziert den gekauften Call durch den Verkauf eines Puts. Bullischer Synthetic zu nahezu null Kosten.",
  "strat_seagull_desc": "Risk Reversal, oben durch einen höher verkauften Call begrenzt: günstiger, dafür ohne den letzten Abschnitt.",
  "strat_big_lizard_desc": "Short Straddle mit darüber gekauftem Call: beseitigt das Aufwärtsrisiko, lässt nur das Abwärtsrisiko.",
  "strat_reverse_jade_desc": "Verkaufter Call plus verkaufter Put-Spread: kein Risiko nach unten, Risiko nach oben.",
  "strat_long_call_condor_desc": "Vier Calls, die ein Gewinnplateau zwischen den beiden inneren Strikes bilden.",
  "strat_long_put_condor_desc": "Derselbe Condor, vollständig aus Puts gebaut.",
  "strat_long_put_butterfly_desc": "Put-Butterfly: Maximum am mittleren Strike, Risiko auf das Debit begrenzt.",
  "strat_put_bwb_desc": "Put-Butterfly mit einem breiteren Flügel. Meist gegen Kredit eröffnet, verlagert das gesamte Risiko auf eine Seite.",
  "strat_xmas_call_desc": "Asymmetrischer 1-3-2-Call-Butterfly: günstiger als der klassische, mit verschobener Gewinnzone.",
  "strat_xmas_put_desc": "Die Put-Variante des 1-3-2-Butterfly, nach unten verschoben.",
  "strat_bull_call_ladder_desc": "Bull Call Spread mit einem dritten, höher verkauften Call. Der Zusatzkredit öffnet unbegrenztes Risiko nach oben.",
  "strat_bear_call_ladder_desc": "Ein Call unten verkauft, zwei oben gekauft: verliert in der Range, gewinnt bei großer Aufwärtsbewegung.",
  "strat_bull_put_ladder_desc": "Ein Put oben verkauft, zwei unten gekauft: verliert in der Range, gewinnt bei starkem Rückgang.",
  "strat_bear_put_ladder_desc": "Bear Put Spread mit einem dritten, tiefer verkauften Put. Der Zusatzkredit öffnet Risiko nach unten.",
