  "calcDescPosition": "Wie viele Einheiten du kaufst, damit du beim Auslösen des Stops genau den Prozentsatz des Kontos verlierst, den du riskieren wolltest. Diese Rechnung kommt VOR dem Einstieg.",
  "calcDescLotsize": "Dasselbe wie die Positionsgröße, aber in Forex-Lots — unter Berücksichtigung des Pip-Werts des Paares und deiner Kontowährung.",
