  "calcDescFutures": "Erforderliche Margin, Tick-Wert und Ergebnis eines Futures-Kontrakts, mit dem jeweiligen Multiplikator des Marktes.",
  "calcDescTarget": "Zu welchem Kurs du verkaufen musst, um den angestrebten Gewinn in Prozent zu erzielen — Gebühren inklusive.",
  "calcDescPercentage": "Wie stark etwas steigen muss, um einen Verlust auszugleichen. Die Asymmetrie überrascht: −50 % erfordern +100 %, nur um wieder bei null zu sein.",
  "calcDescSpot": "Was du beim Kauf oder Verkauf am Spotmarkt tatsächlich bekommst, nach Abzug der Gebühren.",
  "calcDescMeasure": "Das Kursziel, das ein Chartmuster aus seiner eigenen Höhe projiziert — so misst man ein Dreieck, eine SKS oder ein Rechteck.",
