  "calcDescMontecarlo": "Wie sich die Ergebnisse deines Systems verteilen, wenn du dieselben Trades tausendfach in anderer Reihenfolge durchspielst. Zeigt die Verlustserie, die deine Statistik zulässt.",
  "calcDescSimulator": "Wie sich das Konto Phase für Phase entwickelt — mit deinen Risikoregeln und der Frage, wann die Positionsgröße steigen oder sinken sollte.",
  "calcDescCompound": "Wie das Kapital wächst, wenn du die Gewinne reinvestierst — inklusive regelmäßiger Einzahlungen.",
  "helpAria": "Erklärung anzeigen",
  "helpRiskPerTrade": "Der Prozentsatz des Kontos, den du BEI DIESEM Trade zu verlieren bereit bist — nicht insgesamt. Üblich sind 1–2 %: Bei 2 % braucht es rund 35 Verluste in Folge, um das Konto zu halbieren; bei 10 % genügen 7.",
  "helpStopDistance": "Der Abstand zwischen Einstieg und Stop bestimmt die Größe, nicht umgekehrt. Ein engerer Stop erlaubt mehr Einheiten bei gleichem Risiko — wird aber auch öfter ausgelöst.",
  "helpRequiredLeverage": "Der Hebel, den du bräuchtest, um diese Position mit deinem Kapital zu eröffnen. Keine Empfehlung: Ein hoher Wert bedeutet meist, dass der Stop für dein Konto zu weit weg ist — nicht, dass du hebeln solltest.",
  "helpAccountBalance": "Nimm den heutigen echten Kontostand, nicht den erhofften. Die gesamte Risikorechnung hängt an dieser Zahl — sie aufzurunden vergrößert jede einzelne Position.",
  "helpPipValue": "Was die Position gewinnt oder verliert, wenn sich das Paar um einen Pip bewegt. Hängt vom Paar und deiner Kontowährung ab: Ein EURUSD-Pip ist nicht so viel wert wie ein USDJPY-Pip.",
  "helpLotSize": "Ein Standard-Lot sind 100.000 Einheiten der Basiswährung, ein Mini 10.000, ein Micro 1.000. Ein Ergebnis von 0,35 Lots heißt 35.000 Einheiten, nicht 35.",
  "helpLeverage": "Er multipliziert das Ergebnis in beide Richtungen gleich. Bei 10x lässt dich eine 10-%-Bewegung gegen dich nicht bei 90 % stehen — sie liquidiert dich. Die Liquidation kommt vor dem Totalverlust.",
  "helpContractSize": "Jeder Future steht für eine feste Menge des Basiswerts — und die ist nicht überall gleich. Ein E-mini-S&P-Kontrakt bewegt 50 $ pro Punkt, ein Rohöl-Kontrakt 1.000 Barrel. Dieser Multiplikator macht aus einer kleinen Bewegung ein großes Ergebnis.",
  "helpSimulations": "Wie oft deine Trades zufällig neu gemischt werden. Bei wenigen Durchläufen ändert sich das Ergebnis bei jedem Klick; ab etwa 5.000 stabilisieren sich die Perzentile und werden verlässlich.",
  "helpDrawdown": "Der größte Rückgang von einem Kontohoch bis zum darauffolgenden Tief. Diese Zahl entscheidet wirklich, ob du dem System treu bleiben kannst: Kaum jemand handelt eine Serie durch, mit der er nicht gerechnet hat.",
